from search import lower_bound

def test_empty():
    assert lower_bound([], 5) == 0

def test_beyond_end():
    assert lower_bound([1, 3, 5], 6) == 3

def test_below_start():
    assert lower_bound([1, 3, 5], 0) == 0

def test_duplicates():
    assert lower_bound([1, 2, 2, 2, 3], 2) == 1


